import{_ as p,H as a,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"npm：不只是包管理","description":"","frontmatter":{},"headers":[{"level":2,"title":"创建项目","slug":"创建项目","link":"#创建项目","children":[]},{"level":2,"title":"安装和管理依赖","slug":"安装和管理依赖","link":"#安装和管理依赖","children":[]},{"level":2,"title":"自动化构建的场景中安装依赖","slug":"自动化构建的场景中安装依赖","link":"#自动化构建的场景中安装依赖","children":[]},{"level":2,"title":"npm script","slug":"npm-script","link":"#npm-script","children":[]},{"level":2,"title":"发布 npm 包","slug":"发布-npm-包","link":"#发布-npm-包","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"重学前端/npm：不只是包管理.md","filePath":"重学前端/npm：不只是包管理.md","lastUpdated":1779822672000}'),o={name:"重学前端/npm：不只是包管理.md"};function c(t,e,i,l,d,r){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="npm-不只是包管理" tabindex="-1">npm：不只是包管理 <a class="header-anchor" href="#npm-不只是包管理" aria-label="Permalink to &quot;npm：不只是包管理&quot;">​</a></h1><p>你好，我是winter。</p><p>npm 是 Node.js 自带的包管理工具，多数前端同学对它并不陌生， <strong>但是它的功能十分丰富，要想用好 npm，需要从中找到一条线索。</strong></p><p>在本节课中，我们以时间为线索，从创建、安装依赖、运行脚本到最终发布，来讲解 npm 关键的指令用法。</p><h2 id="创建项目" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目" aria-label="Permalink to &quot;创建项目&quot;">​</a></h2><p>我们可以使用 <code>npm init</code> 来创建新的 Node.js 包。运行后，会引导你填写包的基本信息，创建一个新的 <code>package.json</code> 文件。</p><p>现在还可以使用第三方的初始化程序来初始化新的包，使用时加上名称即可 <code>npm init &amp;lt;name&gt;</code> 。npm 会自动下载和安装名为 <code>create-&amp;lt;name&gt;</code> 的包，并执行。</p><p>一些比较重要的初始化程序可以参考下表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/854649/09f36cb453f1cf214028f72bbc9ea948.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/854649/09f36cb453f1cf214028f72bbc9ea948.png" alt=""></a></p><h2 id="安装和管理依赖" tabindex="-1">安装和管理依赖 <a class="header-anchor" href="#安装和管理依赖" aria-label="Permalink to &quot;安装和管理依赖&quot;">​</a></h2><h4 id="区分依赖和开发依赖" tabindex="-1">区分依赖和开发依赖 <a class="header-anchor" href="#区分依赖和开发依赖" aria-label="Permalink to &quot;区分依赖和开发依赖&quot;">​</a></h4><p>如今的 Node.js 生态中，用到三方模块几乎是不可避免的。新人最常犯的错误就是不区分依赖和开发依赖，把所有依赖包都存储到依赖中。这里我们就来讲讲如何判断一个包应当属于依赖项，还是开发依赖项。</p><p><strong>区分的基本原则是用户在不需要修改本包代码的情况下，是否仍然要用到所依赖的包。</strong></p><p>通常 <code>dependencies</code> 的特点是源代码中有直接引用，而 <code>dependencies</code> 则多是开发时用到的开发、测试或构建工具。以下是一些例子：</p><p>典型的 dependencies 例如：</p><ul><li>Web 框架（express、koa）—— 处理 HTTP 请求。</li><li>数据库驱动（mongoose、mysql2、pg）—— 连接数据库。</li><li>认证库（jsonwebtoken、bcrypt）—— 处理用户认证。</li><li>API 请求库（axios、node-fetch）—— 发送网络请求。</li></ul><p>典型的 devDependencies 例如：</p><ul><li>测试框架（jest、mocha）—— 用于编写和运行测试。</li><li>代码检查工具（eslint、prettier）—— 规范代码格式。</li><li>构建工具（webpack、babel、vite）—— 转译代码。</li><li>代码监视工具（nodemon）—— 监听代码变化并自动重启服务。</li><li>类型检查工具（typescript）—— 添加静态类型检查。</li></ul><p>当我们使用 <code>npm install &amp;lt;packagename&gt;</code> 安装特定包时，npm 会自动更新 <code>package.json</code> 文件，添加依赖。</p><p><strong>如果你希望添加的是开发依赖，则应该使用 <code>-D</code> 或者 <code>--save-dev</code> 参数。</strong></p><h4 id="系统工具和开发工具" tabindex="-1">系统工具和开发工具 <a class="header-anchor" href="#系统工具和开发工具" aria-label="Permalink to &quot;系统工具和开发工具&quot;">​</a></h4><p>我们使用 Node.js 开发的工具可以分为两类：</p><ul><li>系统工具：工具本身就是给用户使用的产品，例如 http-server、figlet。</li><li>开发工具：开发中使用的工具，特定项目使用，例如 vite、webpack、nyc。</li></ul><p>早年的 Node.js 生态中，二者并不加以区分，所以多数工具都设计为全局安装。即使用 <code>-g</code> 参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g &amp;lt;name&amp;gt;</span></span></code></pre></div><p>但是对于开发工具而言，这并非好的实践，因为同一开发机上可能存在多个项目目录，而每个项目依赖的工具版本要求可能不一致。所以应该使用 devDependency 来指定工具的版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install --save-dev &amp;lt;package-name&amp;gt;</span></span>
<span class="line"><span>npm install -D &amp;lt;package-name&amp;gt;</span></span></code></pre></div><p>当我们使用工具时，推荐优先使用 <code>npx</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx &amp;lt;package-name&amp;gt;</span></span></code></pre></div><p><code>npx</code> 不但会自动处理全局/当前包依赖，还会自动安装所需的库，并且能够避免全局安装时的权限问题。</p><h4 id="依赖本地开发中的包" tabindex="-1">依赖本地开发中的包 <a class="header-anchor" href="#依赖本地开发中的包" aria-label="Permalink to &quot;依赖本地开发中的包&quot;">​</a></h4><p>如果我们需要在本地同时开发多个包，往往需要在本地协同调试好后再发布，要依赖本地的包，则要使用 <code>npm link</code> 。</p><p><code>npm link</code> 允许你在本地开发包和其他本地项目之间创建一种“链接”关系，使得你能够像使用正式发布的包一样使用本地开发包。</p><p>在你正在开发的包（例如库）目录下运行 <code>npm link</code> ，这个命令会把当前包链接到全局的 node_modules 目录。也就是说，开发包会成为一个本地全局安装的包。</p><p>你可以在需要使用该包的其他项目中运行 <code>npm link &amp;lt;package-name&gt;</code>。这样，项目就会在本地的 node_modules 中创建一个符号链接，指向你刚刚全局安装的本地开发包。</p><p>这样操作之后，修改的代码可以实时生效，在本地调试。调试完毕后，则可以使用 <code>npm unlink</code> 来解除链接。</p><p>要注意，因为 <code>npm link</code> 会产生本地全局安装的包，所以多个项目同时进行时，必须特别注意避免冲突。</p><p>直接把本地路径作为依赖安装也可以做到类似的事情，但因为修改了 <code>package.json</code>，所以只推荐在无需发布的示例代码中使用。</p><h4 id="开发场景中安装依赖" tabindex="-1">开发场景中安装依赖 <a class="header-anchor" href="#开发场景中安装依赖" aria-label="Permalink to &quot;开发场景中安装依赖&quot;">​</a></h4><p>在开发场景中，推荐尽量使用 <code>npm install</code> 来安装依赖，根据 <code>package.json</code> 中的语义化版本号来升级到指定的包。</p><p>语义化版本是一种约定的版本号规范，每个版本号由三个数字组成：</p><ul><li>MAJOR（主版本号）：发生重大变更时递增，可能会引入不兼容的 API 变更。例如，从 1.0.0 更新到 2.0.0，表示可能有破坏性改动，老版本的代码可能无法正常运行。</li><li>MINOR（次版本号）：新增功能时递增，但不会破坏已有功能的兼容性。例如，从 1.2.0 更新到 1.3.0，表示增加了新特性，但不会影响旧代码的运行。</li><li>PATCH（补丁版本号）：修复 Bug 或进行小的改进时递增，且不会影响 API 兼容性。例如，从 1.2.3 更新到 1.2.4，表示仅修复了问题，功能保持不变。</li></ul><p>在 package.json 的依赖管理中，经常会使用 ^、~、&gt;、&lt; 等符号来管理版本范围：</p><ul><li><code>^</code>（Caret 运算符）：允许次版本和补丁版本的更新，但不升级主版本。例如，^1.2.3 允许更新到 1.9.9，但不会更新到 2.0.0。</li><li><code>~</code>（Tilde 运算符）：允许补丁版本的更新，但不升级次版本。例如，~1.2.3 允许更新到 1.2.9，但不会更新到 1.3.0。</li><li><code>&gt;</code> 和 <code>&amp;lt;</code>：分别表示大于或小于某个版本。例如，&gt;1.2.3 允许安装 1.2.4 或 2.0.0 以上的版本，而 &lt;1.2.3 允许安装 1.2.2 或更旧的版本。</li><li><code>&gt;=</code> 和 <code>&amp;lt;=</code>：分别表示大于等于或小于等于某个版本。例如，&gt;=1.2.3 允许安装 1.2.3 及以上版本。</li><li><code>*</code>（星号）：表示任何版本都可以安装，例如 \\* 允许 0.x.x、1.x.x、2.x.x 版本。</li><li><code>latest</code>：表示安装最新的稳定版本，适用于希望始终获取最新版本的情况。</li></ul><p>一般情况下，建议在 <code>package.json</code> 中总是使用 <code>^</code>（Caret 运算符）。针对一些不遵循语义化版本的依赖，则使用精确版本号。</p><p><code>npm install</code> 会创建或更新 <code>package-lock.json</code> 文件。这个文件记录了安装的所有依赖包（包括间接依赖）的精确版本号。</p><p>虽然这个文件是自动生成的，但根据一般的开发习惯，这个文件应该被加入源代码中，并提交到源代码仓库。这样可以精确地知道在代码开发时使用的所有第三方依赖的版本号，有利于修复和追踪因为第三方包根据语义化版本自动更新而导致的 Bug。</p><h2 id="自动化构建的场景中安装依赖" tabindex="-1">自动化构建的场景中安装依赖 <a class="header-anchor" href="#自动化构建的场景中安装依赖" aria-label="Permalink to &quot;自动化构建的场景中安装依赖&quot;">​</a></h2><p>除了日常开发，我们有时需要自动化构建源代码到目标代码，典型的场景如发布、持续继承，这样的场景与开发场景有很大区别。有以下特点：</p><ul><li>对性能更敏感，希望尽量缩短安装依赖和构建的时间。</li><li>因为没有开发者参与，没有机会修正问题，所以需要精确控制版本号</li></ul><p>针对这个场景，npm 有对应的命令 <code>npm ci</code>（Clear Install）来安装依赖。它跟 <code>npm install</code> 的区别是：</p><ul><li>它总是清空node_modules目录，全新安装依赖。</li><li>它总是使用 <code>package-lock.json</code> 中的精确版本号来安装依赖。</li></ul><p>但考虑到， <strong>在自动化场景下安装依赖的性能比开发场景下更为重要（如发布时，安装依赖的性能决定了发布的延迟时间），我们必须更加关注缓存问题。</strong></p><p>我们可以给 <code>npm ci</code> 加上参数 <code>--prefer-offline</code> 来确保它优先使用本地缓存，这会大大提升安装的性能。</p><p>在此基础上我们必须要设计好缓存方案，尽可能让本地缓存中有每次安装时需要的包。自动化场景本身较为复杂多样，缓存方案也有多个选项，这里介绍三个典型的方案。</p><p>方案一，直接在构建服务器或者其使用的 Docker 镜像中预先缓存。</p><p>在初始化构建服务器或者其 Docker 镜像时，可以使用 <code>npm cache add &amp;lt;package-name&gt;@&amp;lt;version&gt;</code> 缓存到 npm 默认缓存目录。也可使用参数 <code>--cache &amp;lt;path&gt;</code> 来手工指定缓存目录，如果有手工指定，那么每次安装依赖时也应该使用相同的参数指定缓存目录。</p><p>这种方法优点是性能高且容易操作，缺点是更新困难，且在项目依赖变化较大时，未更新的缓存难以命中。</p><p>方案二，使用持续集成框架自带的文件缓存，多数持续集成框架都允许把构建时产生的临时文件缓存到云存储服务，我们可以把 npm 的默认或者手工缓存目录也利用此机制。</p><p>例如，在 gitlab-ci 的 yml 配置文件中添加以下代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cache:</span></span>
<span class="line"><span>  paths:</span></span>
<span class="line"><span>    - .npm/</span></span></code></pre></div><p>此方法优点是可以随着每次安装自动更新缓存的包，缺点是缓存如不定期清理会越来越大，且仍然需要网络请求，依赖持续集成框架本身的机制的效率，如果持续集成框架本身的网络传输效率不高，或者与云存储配合不好，则会进一步放大网络消耗的时间。</p><p>方案三，自建 npm 源，把公网的 npm 包尽量缓存到本地网络的 npm 源。</p><p>npm 本身有开源 Registry 代码，Nexus 等包管理仓库也提供 npm 源，在本地搭建 npm 源服务器后，通过 <code>--registry</code> 参数或者 <code>.npm</code> 配置文件，可以指定 npm 源到本地源服务。</p><p>此方法优点是按需缓存，管理缓存比较先进，还可以发布私有包，缺点是搭建和维护有一定的挑战，且仍有少量网络开销。</p><p>上述三种方案各有优缺点，在实际的工程环境中，需要结合团队和基建的实际情况，经过多方权衡来考虑如何选择。</p><h2 id="npm-script" tabindex="-1">npm script <a class="header-anchor" href="#npm-script" aria-label="Permalink to &quot;npm script&quot;">​</a></h2><p>为了方便运行工具，npm 提供了一套 npm script 机制。</p><p>我们可以在 <code>package.json</code> 的 scripts 中，配置自己的命令，并通过 <code>npm run &amp;lt;cmd&gt;</code> 来执行。</p><p>这一机制有效引导了 Node 社区的开发习惯，遵循 npm script 使用习惯，可以更容易让新接手项目的开发者找到开发所需的工具。</p><p><code>package.json</code> 的示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;scripts&quot;: {</span></span>
<span class="line"><span>    &quot;dev&quot;: &quot;vite&quot;,</span></span>
<span class="line"><span>    &quot;build&quot;: &quot;vite build&quot;,</span></span>
<span class="line"><span>    &quot;preview&quot;: &quot;vite preview&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>scripts 以键值对的形式定义了扩展的 npm 命令，其中，key 的部分是命令名称，值的部分是对应的 shell 命令。</p><p>值得注意的是，npm script 中，默认在可执行路径添加了本包依赖的 <code>node_modules/.bin</code>，这意味着我们在 <code>devDependencies</code> 中添加的工具都可以无需指定路径直接执行，这与 <code>npx</code> 的逻辑较为类似。</p><p>npm script 中有两个特殊的命令，可以无需 <code>run</code> 执行。</p><ul><li><code>npm start</code> 可以直接执行 <code>scripts.start</code>，如果没有 <code>start</code>，则会查找本包根目录的 <code>server.js</code> 文件，如果有，则会在 Node 中执行。此命令一般用于启动服务器。</li><li><code>npm test</code> 可以直接执行 <code>scripts.test</code>，此命令一般用于运行单元测试脚本。</li></ul><h2 id="发布-npm-包" tabindex="-1">发布 npm 包 <a class="header-anchor" href="#发布-npm-包" aria-label="Permalink to &quot;发布 npm 包&quot;">​</a></h2><p><code>npm publish</code> 命令把 Node 包发布到有效的 Node.js 源，默认的是官方源 npmjs.org。</p><p><code>package.json</code> 中的 <code>main</code>、 <code>files</code> 字段可以帮助你控制发布到 npm 上的包的内容，确保发布的包仅包含必要的文件，并且符合预期的使用方式。</p><p><code>main</code> 字段用于指定包的入口文件。这个文件通常是别人通过 <code>require</code> 或 <code>import</code> 导入你的包时会首先加载的文件。通常，它指向的是包的核心模块（例如 index.js）。它不影响发布包的内容，只是告诉 npm 当别人引入这个包时应该加载哪个文件。</p><p><code>files</code> 字段允许你明确指定哪些文件和目录应该被包含在发布的包中。这能帮助你排除不必要的文件，如文档、测试代码、构建文件等。比如你可以指定只包含 <code>dist/</code> 目录和 <code>LICENSE</code> 文件，这样其他文件比如 <code>test/</code> 目录就不会被发布。files 的作用是对包的发布内容进行精细控制，只有在这个字段列出的文件才会被包含在最终发布的包中。</p><p>如果没有 <code>files</code> 字段，则默认发布整个源码仓库，可以用 <code>.npmignore</code> 排除一些文件。</p><p>在现在的 Node.js 社区，最佳实践是发布构建后的代码。这样做有明显的优点，包括：</p><ul><li>减少包的体积</li><li>兼容低版本语法</li><li>同时支持 TS 和 JS（如果你的源代码是TS）</li></ul><p>我们可以使用 <code>prepublishOnly</code> 脚本来确保每次发布前都进行了构建。此脚本会在每次运行 <code>npm publish</code> 前自动执行。</p><p><code>package.json</code> 中的 <code>bin</code> 字段可以让我们安装时把脚本文件加入可执行目录，这与 <code>npm script</code> 的机制相对应。</p><p>可以通过操作系统的 Shebang 机制把 Node.js 文件变成可执行的脚本，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/usr/bin/env node</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//javascript code</span></span></code></pre></div><p>再把可执行脚本的路径加入 <code>bin</code> 字段。如果有多个命令入口， <code>bin</code> 字段还支持以键值对的方式加入多个命令。</p><p>一个典型的发布构建后文件的 <code>package.json</code> 文件（片段）如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;main&quot;: &quot;dist/index.js&quot;,</span></span>
<span class="line"><span>  &quot;files&quot;: [&quot;dist/&quot;, &quot;LICENSE&quot;],</span></span>
<span class="line"><span>  &quot;script&quot;: {</span></span>
<span class="line"><span>    &quot;cmd1&quot;: &quot;/scripts/cmd1&quot;,</span></span>
<span class="line"><span>    &quot;cmd2&quot;: &quot;/scripts/cmd2&quot;</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  &quot;scripts&quot;: {</span></span>
<span class="line"><span>    &quot;build&quot;: &quot;......&quot;,</span></span>
<span class="line"><span>    &quot;prepublishOnly&quot;: &quot;npm run build&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本节课，我们从初始化包、安装依赖、执行脚本、发布几个方面讲解了 npm 的使用原则和技巧，这涵盖了一个包的完整的开发流程。</p>`,93)])])}const h=p(o,[["render",c]]);export{u as __pageData,h as default};
